-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `vista_comercio_por_pais`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_comercio_por_pais` AS SELECT p.p_nombre AS pais, tc.tc_descrip AS tipo_comercio, ce.ce_descrip AS categoria_economica, rue.rue_descrip AS rubro, ic.ic_anio AS anio, ic.ic_mes AS mes, SUM(ic.ic_valor) AS valor_total
FROM intercambiocomercial ic, pais p, tipocomercio tc, categoriaeconomica ce, rubrousoeconomico rue
WHERE ic.ic_pais = p.p_codi AND ic.ic_tipo = tc.tc_codi AND  ic.ic_categoriae = ce.ce_codi AND ce.ce_rue = rue.rue_codi
GROUP BY pais, tipo_comercio, categoria_economica, rubro,anio, mes 
;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `vista_intercambio_detallado`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_intercambio_detallado` AS SELECT ic.ic_codi AS codigo, ic.ic_anio AS anio, ic.ic_mes AS mes, tc.tc_descrip AS tipo_comercio, p.p_nombre AS pais, zc.zc_nombre AS zona_comercial, rue.rue_descrip AS rubro_uso_economico, ce.ce_descrip AS categoria_economica, ic.ic_valor AS valor
FROM intercambiocomercial ic, tipocomercio tc, pais p, zonacomercial zc, categoriaeconomica ce, rubrousoeconomico rue
WHERE ic.ic_tipo = tc.tc_codi AND ic.ic_pais = p.p_codi AND p.p_zonac = zc.zc_codi AND ic.ic_categoriae = ce.ce_codi AND ce.ce_rue = rue.rue_codi 
;

