DROP TABLE IF EXISTS `vista_totales_por_categoria`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vista_totales_por_categoria` AS SELECT ic.ic_anio AS anio, ic.ic_mes AS mes, tc.tc_descrip AS tipo_comercio, rue.rue_descrip AS rubro_uso_economico, ce.ce_descrip AS categoria_economica, SUM(ic.ic_valor) AS total_valor
FROM intercambiocomercial ic, tipocomercio tc, categoriaeconomica ce, rubrousoeconomico rue
WHERE ic.ic_tipo = tc.tc_codi AND ic.ic_categoriae = ce.ce_codi AND ce.ce_rue = rue.rue_codi
